const recoverQueuedStorageArchives = `-- name: RecoverQueuedStorageArchives :many
SELECT o.id FROM hosting_operations o JOIN hosting_storage_archive_plans p ON p.operation_id=o.id WHERE o.state='queued' AND o.run_id IS NULL ORDER BY o.updated_at,o.id LIMIT 100 FOR UPDATE OF o SKIP LOCKED
`

func (q *Queries) RecoverQueuedStorageArchives(ctx context.Context) ([]string, error) {
	rows, err := q.db.Query(ctx, recoverQueuedStorageArchives)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []string{}
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

